    fn authHeaders(self: *const @This()) ?[]const [2][]const u8 {
        if (self.auth_header) |*h| return @as(*const [1][2][]const u8, h);
        return null;
    }

    fn freeAuth(self: *@This()) void {
        if (self.auth_header) |h| {
            self.allocator.free(h[1]);
            self.auth_header = null;
        }
    }
